	@Test
	void exclusiveStatementMatchesWithExplicitNullForCapturedPredicate() throws Exception {
		var endpoint = prepareTest(List.of("/tests/basic/data_emptyStore.ttl")).get(0);
		var predicate = Values.iri("urn:predicate");
		var subject = Values.iri("urn:subject");
		var object = Values.literal("object");
		try (var connection = getRepository(1).getConnection()) {
			connection.add(subject, predicate, object);
			connection.add(subject, Values.iri("urn:other-predicate"), Values.literal("other object"));
		}

		var context = federationContext();
		var strategy = context.createStrategy(null);
		var queryInfo = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
		try {
			var statement = new ExclusiveStatement(
					new StatementPattern(Var.of("s"), Var.of("p", predicate, false, false), Var.of("o")),
					new StatementSource(endpoint.getId(), StatementSourceType.REMOTE), queryInfo);
			try (var rows = statement.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(QueryResults.asList(rows)).singleElement()
						.satisfies(row -> assertThat(row.getValue("p")).isEqualTo(predicate));
			}
			var bindings = new QueryBindingSet();
			bindings.setBinding("p", null);
			try (var rows = statement.evaluate(bindings)) {
				assertThat(QueryResults.asList(rows)).singleElement().satisfies(row -> {
					assertThat(row.getValue("p")).isEqualTo(predicate);
					assertThat(row.getValue("o")).isEqualTo(object);
				});
			}
		} finally {
			queryInfo.close();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void apiBoundPredicateStillUsesOneRequestPerJoinBlock(boolean optional) throws Exception {
		assumeSparqlEndpoint();
		prepareTest(List.of("/tests/basic/data_emptyStore.ttl", "/tests/basic/data_emptyStore.ttl"));
		fedxRule.setConfig(config -> config.withBoundJoinBlockSize(20).withEnableOptionalAsBindJoin(true));
		var predicate = Values.iri("urn:predicate");
		var seed = Values.iri("urn:seed");
		var a = Values.iri("urn:a");
		var b = Values.iri("urn:b");
		var c = Values.iri("urn:c");
		try (var left = getRepository(1).getConnection(); var right = getRepository(2).getConnection()) {
			left.add(a, seed, Values.literal(1));
			left.add(a, seed, Values.literal(2));
			left.add(b, seed, Values.literal(3));
			left.add(c, seed, Values.literal(4));
			right.add(a, predicate, Values.literal("first"));
			right.add(a, predicate, Values.literal("second"));
			right.add(b, predicate, Values.literal("third"));
			right.add(b, seed, Values.literal("different predicate"));
		}

		String rightPattern = optional ? "OPTIONAL { ?s ?p ?value }" : "?s ?p ?value";
		try (var connection = fedxRule.getRepository().getConnection()) {
			var query = connection.prepareTupleQuery("""
					SELECT ?s ?p ?value WHERE {
					  { SELECT ?s WHERE { ?s <urn:seed> ?seed } }
					  %s
					}
					""".formatted(rightPattern));
			query.setBinding("p", predicate);
			// Warm source selection before counting endpoint requests for the evaluation itself.
			try (var result = query.evaluate()) {
				QueryResults.asList(result);
			}
			federationContext().getMonitoringService().resetMonitoringInformation();

			var expected = new ArrayList<List<Value>>(List.of(
					List.of(a, predicate, Values.literal("first")),
					List.of(a, predicate, Values.literal("second")),
					List.of(a, predicate, Values.literal("first")),
					List.of(a, predicate, Values.literal("second")),
					List.of(b, predicate, Values.literal("third")),
					List.of(b, predicate, Values.literal("third"))));
			if (optional) {
				expected.add(Arrays.asList(c, null, null));
			}
			try (var result = query.evaluate()) {
				assertThat(QueryResults.asList(result))
						.extracting(row -> Arrays.asList(row.getValue("s"), row.getValue("p"), row.getValue("value")))
						.containsExactlyInAnyOrderElementsOf(expected);
			}
			// Endpoint 2 sees one seed query on the left and one VALUES query for the whole right-hand block.
			assertNumberOfRequests("endpoint2", 2);
		}
	}

